import static org.mockito.Mockito.when;

public class DatasetUtilities_iterateDomainBounds_TriageGen0Test {

    @Mock
    private XYDataset mockXYDataset;

    @Mock
    private IntervalXYDataset mockIntervalXYDataset;

    public DatasetUtilities_iterateDomainBounds_TriageGen0Test() {
        MockitoAnnotations.openMocks(this);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testIterateDomainBounds_NullDataset() {
        DatasetUtilities.iterateDomainBounds(null, false);
    }

    @Test
    public void testIterateDomainBounds_EmptyDataset() {
        when(mockXYDataset.getSeriesCount()).thenReturn(0);
        Range result = DatasetUtilities.iterateDomainBounds(mockXYDataset, false);
        assertNull(result);
    }

    @Test
    public void testIterateDomainBounds_StandardXYDataset_SingleValue() {
        when(mockXYDataset.getSeriesCount()).thenReturn(1);
        when(mockXYDataset.getItemCount(0)).thenReturn(1);
        when(mockXYDataset.getXValue(0, 0)).thenReturn(10.0);

        Range result = DatasetUtilities.iterateDomainBounds(mockXYDataset, false);

        assertEquals(10.0, result.getLower(), 1e-10);
        assertEquals(10.0, result.getUpper(), 1e-10);
    }

    @Test
    public void testIterateDomainBounds_StandardXYDataset_MultipleValues() {
        when(mockXYDataset.getSeriesCount()).thenReturn(1);
        when(mockXYDataset.getItemCount(0)).thenReturn(2);
        when(mockXYDataset.getXValue(0, 0)).thenReturn(5.0);
        when(mockXYDataset.getXValue(0, 1)).thenReturn(15.0);

        Range result = DatasetUtilities.iterateDomainBounds(mockXYDataset, false);

        assertEquals(5.0, result.getLower(), 1e-10);
        assertEquals(15.0, result.getUpper(), 1e-10);
    }

    @Test
    public void testIterateDomainBounds_StandardXYDataset_WithNaN() {
        when(mockXYDataset.getSeriesCount()).thenReturn(1);
        when(mockXYDataset.getItemCount(0)).thenReturn(2);
        when(mockXYDataset.getXValue(0, 0)).thenReturn(Double.NaN);
        when(mockXYDataset.getXValue(0, 1)).thenReturn(20.0);

        Range result = DatasetUtilities.iterateDomainBounds(mockXYDataset, false);

        assertEquals(20.0, result.getLower(), 1e-10);
        assertEquals(20.0, result.getUpper(), 1e-10);
    }

    @Test
    public void testIterateDomainBounds_IntervalXYDataset_IncludeInterval_True() {
        // Use IntervalXYDataset branch
        when(mockIntervalXYDataset.getSeriesCount()).thenReturn(1);
        when(mockIntervalXYDataset.getItemCount(0)).thenReturn(1);

        // XValue = 10, Start = 5, End = 15
        when(mockIntervalXYDataset.getXValue(0, 0)).thenReturn(10.0);
        when(mockIntervalXYDataset.getStartXValue(0, 0)).thenReturn(5.0);
        when(mockIntervalXYDataset.getEndXValue(0, 0)).thenReturn(15.0);

        Range result = DatasetUtilities.iterateDomainBounds(mockIntervalXYDataset, true);

        assertEquals(5.0, result.getLower(), 1e-10);
        assertEquals(15.0, result.getUpper(), 1e-10);
    }

    @Test
    public void testIterateDomainBounds_IntervalXYDataset_IncludeInterval_WithNaN() {
        when(mockIntervalXYDataset.getSeriesCount()).thenReturn(1);
        when(mockIntervalXYDataset.getItemCount(0)).thenReturn(1);

        // XValue = NaN, Start = 5, End = 15
        when(mockIntervalXYDataset.getXValue(0, 0)).thenReturn(Double.NaN);
        when(mockIntervalXYDataset.getStartXValue(0, 0)).thenReturn(5.0);
        when(mockIntervalXYDataset.getEndXValue(0, 0)).thenReturn(15.0);

        Range result = DatasetUtilities.iterateDomainBounds(mockIntervalXYDataset, true);

        assertEquals(5.0, result.getLower(), 1e-10);
        assertEquals(15.0, result.getUpper(), 1e-10);
    }

    @Test
    public void testIterateDomainBounds_IntervalXYDataset_IncludeInterval_StartNaN() {
        when(mockIntervalXYDataset.getSeriesCount()).thenReturn(1);
        when(mockIntervalXYDataset.getItemCount(0)).thenReturn(1);

        // XValue = 10, Start = NaN, End = 15
        when(mockIntervalXYDataset.getXValue(0, 0)).thenReturn(10.0);
        when(mockIntervalXYDataset.getStartXValue(0, 0)).thenReturn(Double.NaN);
        when(mockIntervalXYDataset.getEndXValue(0, 0)).thenReturn(15.0);

        Range result = DatasetUtilities.iterateDomainBounds(mockIntervalXYDataset, true);

        assertEquals(10.0, result.getLower(), 1e-10);
        assertEquals(15.0, result.getUpper(), 1e-10);
    }

    @Test
    public void testIterateDomainBounds_IncludeInterval_False_OnIntervalDataset() {
        // When includeInterval is false, it should treat IntervalXYDataset as regular XYDataset
        when(mockIntervalXYDataset.getSeriesCount()).thenReturn(1);
        when(mockIntervalXYDataset.getItemCount(0)).thenReturn(1);
        when(mockIntervalXYDataset.getXValue(0, 0)).thenReturn(10.0);

        Range result = DatasetUtilities.iterateDomainBounds(mockIntervalXYDataset, false);

        assertEquals(10.0, result.getLower(), 1e-10);
        assertEquals(10.0, result.getUpper(), 1e-10);
    }

    @Test
    public void testIterateDomainBounds_AllNaN_ReturnsNull() {
        when(mockXYDataset.getSeriesCount()).thenReturn(1);
        when(mockXYDataset.getItemCount(0)).thenReturn(1);
        when(mockXYDataset.getXValue(0, 0)).thenReturn(Double.NaN);

        Range result = DatasetUtilities.iterateDomainBounds(mockXYDataset, false);

        assertNull(result);
    }
}
